/**
 * Architecture Contract: Arweave Service
 * Codifies the public interface of services/arweave.js.
 * Generated by /architecture-sweep
 */

// Mock env must be set before require
process.env.USE_MOCK_ARWEAVE = 'true';
process.env.NODE_ENV = 'test';

const arweaveService = require('../../src/services/arweave');

describe('Arweave service interface contract', () => {
  // ── Module exports ──

  test('exports expected public functions', () => {
    expect(typeof arweaveService.upload).toBe('function');
    expect(typeof arweaveService.uploadJson).toBe('function');
    expect(typeof arweaveService.getGatewayUrl).toBe('function');
    expect(typeof arweaveService.fetchData).toBe('function');
    expect(typeof arweaveService.fetchMetadata).toBe('function');
    expect(typeof arweaveService.getStatus).toBe('function');
    expect(typeof arweaveService.getBalance).toBe('function');
    expect(typeof arweaveService.estimateCost).toBe('function');
    expect(typeof arweaveService.verifyHash).toBe('function');
  });

  test('does not export internal helpers', () => {
    expect(arweaveService.getArweave).toBeUndefined();
    expect(arweaveService.getWallet).toBeUndefined();
    expect(arweaveService.saveMockStore).toBeUndefined();
  });

  // ── upload() ──

  test('upload returns [result, events] tuple', async () => {
    const data = Buffer.from('test arweave data');
    const result = await arweaveService.upload(data, 'application/json');

    expect(Array.isArray(result)).toBe(true);
    expect(result.length).toBe(2);

    const [res, events] = result;
    expect(typeof res.txId).toBe('string');
    expect(typeof res.hash).toBe('string');
    expect(res.hash.startsWith('0x')).toBe(true);
    expect(Array.isArray(events)).toBe(true);
    expect(events[0].type).toBe('arweave.uploaded');
    expect(events[0].mock).toBe(true);
  });

  // ── uploadJson() ──

  test('uploadJson returns [result, events] tuple', async () => {
    const json = { name: 'Test', description: 'Test metadata' };
    const result = await arweaveService.uploadJson(json);

    expect(Array.isArray(result)).toBe(true);
    const [res, events] = result;
    expect(typeof res.txId).toBe('string');
    expect(typeof res.hash).toBe('string');
    expect(events[0].type).toBe('arweave.uploaded');
  });

  // ── getGatewayUrl() ──

  test('getGatewayUrl returns URL for mock mode', () => {
    const url = arweaveService.getGatewayUrl('mock_test_tx_id');
    expect(typeof url).toBe('string');
    expect(url).toContain('mock_test_tx_id');
  });

  // ── fetchData() ──

  test('fetchData retrieves previously uploaded data', async () => {
    const data = Buffer.from('roundtrip arweave test');
    const [{ txId }] = await arweaveService.upload(data, 'text/plain');

    const fetched = await arweaveService.fetchData(txId);
    expect(Buffer.isBuffer(fetched)).toBe(true);
    expect(fetched.equals(data)).toBe(true);
  });

  test('fetchData throws for non-existent txId', async () => {
    await expect(arweaveService.fetchData('non_existent_tx'))
      .rejects.toThrow();
  });

  // ── fetchMetadata() ──

  test('fetchMetadata parses JSON from uploaded data', async () => {
    const metadata = { name: 'Art #1', description: 'Beautiful art' };
    const [{ txId }] = await arweaveService.uploadJson(metadata);

    const fetched = await arweaveService.fetchMetadata(txId);
    expect(fetched.name).toBe('Art #1');
    expect(fetched.description).toBe('Beautiful art');
  });

  test('fetchMetadata handles ar:// URI prefix', async () => {
    const metadata = { name: 'Art #2' };
    const [{ txId }] = await arweaveService.uploadJson(metadata);

    const fetched = await arweaveService.fetchMetadata(`ar://${txId}`);
    expect(fetched.name).toBe('Art #2');
  });

  // ── getStatus() ──

  test('getStatus returns confirmed status for uploaded data', async () => {
    const [{ txId }] = await arweaveService.upload(Buffer.from('status test'), 'text/plain');

    const status = await arweaveService.getStatus(txId);
    expect(typeof status.confirmed).toBe('boolean');
    expect(status.confirmed).toBe(true);
    expect(typeof status.blockHeight).toBe('number');
  });

  test('getStatus returns unconfirmed for non-existent txId', async () => {
    const status = await arweaveService.getStatus('non_existent');
    expect(status.confirmed).toBe(false);
    expect(status.blockHeight).toBeNull();
  });

  // ── getBalance() ──

  test('getBalance returns a string in mock mode', async () => {
    const balance = await arweaveService.getBalance();
    expect(typeof balance).toBe('string');
  });

  // ── estimateCost() ──

  test('estimateCost returns winston and ar fields', async () => {
    const cost = await arweaveService.estimateCost(1024);
    expect(typeof cost.winston).toBe('string');
    expect(typeof cost.ar).toBe('string');
  });

  // ── verifyHash() ──

  test('verifyHash returns true for matching content', async () => {
    const data = Buffer.from('hash verify test');
    const [{ txId, hash }] = await arweaveService.upload(data, 'text/plain');

    const verified = await arweaveService.verifyHash(txId, hash);
    expect(verified).toBe(true);
  });

  test('verifyHash returns false for mismatched hash', async () => {
    const data = Buffer.from('hash mismatch test');
    const [{ txId }] = await arweaveService.upload(data, 'text/plain');

    const verified = await arweaveService.verifyHash(txId, '0xdeadbeef');
    expect(verified).toBe(false);
  });

  // ── Event generation ──

  test('upload generates arweave.uploaded events with expected fields', async () => {
    const [, events] = await arweaveService.upload(Buffer.from('event test'), 'text/plain');
    const e = events[0];
    expect(e).toHaveProperty('type', 'arweave.uploaded');
    expect(e).toHaveProperty('txId');
    expect(e).toHaveProperty('hash');
    expect(e).toHaveProperty('contentType', 'text/plain');
    expect(e).toHaveProperty('mock');
    expect(e).toHaveProperty('timestamp');
  });
});
